/**
 * Emoji dataset for the picker modal (search + browse). Curated, categorized,
 * with search keywords, baked in so it is instant and offline. Generated by the
 * emoji-picker-data workflow; replace EMOJI_GROUPS to refresh.
 *
 * This is separate from emojiKeywords.ts (which powers title auto-suggest).
 */

export interface EmojiEntry {
  /** the emoji character */
  e: string
  /** search keywords (lowercase) */
  k: string[]
}

export interface EmojiGroup {
  name: string
  items: EmojiEntry[]
}

/** flat, deduped list of all emoji in browse order */
export function allEmojis(): string[] {
  const seen = new Set<string>()
  const out: string[] = []
  for (const g of EMOJI_GROUPS) {
    for (const it of g.items) {
      if (!seen.has(it.e)) {
        seen.add(it.e)
        out.push(it.e)
      }
    }
  }
  return out
}

/** keyword search: matches the emoji whose keywords start-with / contain the query tokens */
export function searchEmojis(query: string): string[] {
  const q = query.trim().toLowerCase()
  if (!q) return []
  const tokens = q.split(/\s+/)
  const scored: { e: string; score: number }[] = []
  const seen = new Set<string>()
  for (const g of EMOJI_GROUPS) {
    for (const it of g.items) {
      if (seen.has(it.e)) continue
      let score = 0
      for (const t of tokens) {
        const exact = it.k.some((k) => k === t)
        const prefix = it.k.some((k) => k.startsWith(t))
        const contains = it.k.some((k) => k.includes(t))
        if (exact) score += 3
        else if (prefix) score += 2
        else if (contains) score += 1
        else {
          score = -1
          break
        }
      }
      if (score > 0) {
        seen.add(it.e)
        scored.push({ e: it.e, score })
      }
    }
  }
  return scored.sort((a, b) => b.score - a.score).map((s) => s.e).slice(0, 60)
}

